const SPECS = [{"number": 82, "oldTitle": "Story 82: Pudding & the Wobbliest Bridge", "newTitle": "Story 82: Iron Egg & the Lost-and-Found Lighthouse", "newSlug": "iron-egg-and-the-lost-and-found-lighthouse", "mainCharacter": "Tiě Dàn (Iron Egg) — a tiny, dark, chewy salt-and-soy braised egg from Tamsui, gruff and crusty on the outside", "setting": "The old Tamsui (Danshui) harbor and its red-brick lighthouse at dusk", "theme": "What looks tough on the outside can be the gentlest helper of all", "spotlightTerm": "燈塔", "spotlightRomanization": "dēngtǎ", "spotlightMeaning": "lighthouse", "premise": "Crusty little Iron Egg is sure his hard, wrinkled shell means he's no good for soft jobs, until the harbor lighthouse keeper falls ill and a fog rolls in. Iron Egg discovers his dark, dense little body is the perfect weight to keep the signal-lantern's pulley steady, and his gruff foghorn voice gently calls every lost fishing-snack safely back to the docks.", "arc": "Iron Egg grumbles that nobody wants a tough, ugly snack -> fog swallows the harbor and a boat of little snacks can't find shore -> the lighthouse lamp keeps slipping -> Iron Egg anchors the pulley with his weight and booms a soft, steady call across the water -> every boat finds home, and the toughest snack turns out to be the warmest beacon.", "reason": "Chosen over canonical #17 (Pudding/Wobble) because #82 repeated the exact 'wobbly Pudding learns wobbling-forward-still-counts' epiphany already locked in #17 and #31. Switched to a brand-new under-used character (Iron Egg/Tamsui specialty), a navigation-rescue plot instead of a balance/crossing test, and a fresh lesson about a tough exterior hiding a tender helper — distinct from the embrace-imperfection theme.", "collection": "taiwan", "path": "stories/82-iron-egg-and-the-lost-and-found-lighthouse.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 87, "oldTitle": "Story 87: Douhua & the Still Temple Pond", "newTitle": "Story 87: Wintermelon Tea & the Sound-Collector's Jar", "newSlug": "wintermelon-tea-and-the-sound-collectors-jar", "mainCharacter": "Dōngguā Chá (Wintermelon Tea) — a tall, amber, sweet-and-cooling drink in a glass bottle, an absent-minded collector", "setting": "A cluttered old apothecary-and-bottle shop in Tainan's lantern-lit back lanes", "theme": "Listening closely is a kind of giving", "spotlightTerm": "聽", "spotlightRomanization": "tīng", "spotlightMeaning": "to listen", "premise": "Chatty Wintermelon Tea loves collecting interesting sounds in empty glass jars, but when a lonely new snack arrives who is too sad to speak, his jars stay empty. He learns to stop talking and simply listen — and discovers that letting someone be heard is the most generous gift of all, filling his quietest jar with the truest sound.", "arc": "Wintermelon Tea proudly shows off his jars of bottled sounds -> a hushed, homesick newcomer won't say a word, so the collector has nothing to catch -> he keeps chattering and filling the silence himself, missing the point -> he finally goes quiet and listens with his whole glassy self -> the newcomer opens up, and that gentle telling becomes the most precious sound he's ever kept.", "reason": "Chosen over #65 (Beitou Hot Spring, kept as the canonical Douhua-calms-anxiety story) because #87 ran the same 'serene Douhua helps an anxious snack let a worry float away' beat. Switched to a fresh character (Wintermelon Tea), a sound-collecting whimsy plot, and a distinct theme about active listening rather than stillness/breathing — no other story is about listening as generosity.", "collection": "taiwan", "path": "stories/87-wintermelon-tea-and-the-sound-collectors-jar.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 77, "oldTitle": "Story 77: Chicken Cutlet & the Gentle-Giant Games", "newTitle": "Story 77: Salty Crisp Chicken & the Spice-Drawer Mystery", "newSlug": "salty-crisp-chicken-and-the-spice-drawer-mystery", "mainCharacter": "Yán Sū Jī (Salt-and-Pepper Crispy Chicken) — a crunchy, basil-flecked fried snack with a detective's magnifying glass", "setting": "A bustling Shilin night-market fry stall after closing, lit by a single bulb", "theme": "Curiosity solves more than strength ever could", "spotlightTerm": "為什麼", "spotlightRomanization": "wèishéme", "spotlightMeaning": "why", "premise": "When the stall's beloved spice drawer goes missing right before the morning rush, self-styled detective Salty Crisp Chicken cracks the case not by being the biggest or boldest but by asking 'why' and 'why' and 'why' again, following a trail of fragrant basil leaves to a sleepy mouse who only wanted to smell something nice.", "arc": "The whole stall panics — no spices means no flavor for tomorrow -> Salty Crisp Chicken refuses to just shove things around and instead investigates clues -> wrong guesses and silly red herrings (a sneeze, a runaway peppercorn) -> the basil trail leads to a tiny mouse nest -> gentle questioning solves it, the spices come home, and curiosity wins the day.", "reason": "Chosen over canonical #46 (Bigger-Than-Your-Face) because #77 repeated the exact 'big spotlight-loving Pái Pái gives up her moment for a smaller friend' self-sacrifice arc. Switched to a different fried-chicken character (Salt-and-Pepper Crispy Chicken), a mystery/detective plot, and a brand-new curiosity-over-strength theme — replacing the self-sacrifice lesson entirely.", "collection": "taiwan", "path": "stories/77-salty-crisp-chicken-and-the-spice-drawer-mystery.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 80, "oldTitle": "Story 80: Mango & the Round-the-Island Relay", "newTitle": "Story 80: Bubble Waffle Sisters & the Kite Festival Sky", "newSlug": "bubble-waffle-sisters-and-the-kite-festival-sky", "mainCharacter": "Shuāng Bāo Tāi (the Double-Bun Twins) — two fried twin-dough buns joined at the middle, one daring and one cautious", "setting": "The windy grassy hills of a Hsinchu kite festival on a blustery afternoon", "theme": "Two who pull in different directions can still fly the same kite", "spotlightTerm": "風箏", "spotlightRomanization": "fēngzheng", "spotlightMeaning": "kite", "premise": "The Double-Bun Twins want to launch the grandest kite at the festival, but one twin yanks the string tight while the other lets it loose, and their kite keeps nose-diving. They learn that flying isn't about one of them winning the tug — it's about feeling the wind together and pulling at the same gentle moment.", "arc": "The joined twins each grab an end of the kite string and argue over technique -> crash after embarrassing crash on the hill -> they stop competing and start listening to the wind -> they discover that taking turns easing and tugging makes the kite soar -> their kite climbs highest of all, lifted by their teamwork, not their tugging.", "reason": "Chosen over #60 (Mango Capital Race, kept) because #80 was yet another competitive-Mango relay/race with the 'we carry each other to the finish' lesson already covered by #8, #26, and #60. Switched to a new under-used character (the Double-Bun Twins), a kite-flying activity instead of a race, and a distinct cooperation-through-difference theme rather than a finish-line lesson.", "collection": "taiwan", "path": "stories/80-bubble-waffle-sisters-and-the-kite-festival-sky.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 73, "oldTitle": "Story 73: Sesame Ball & the Great Rolling Tournament", "newTitle": "Story 73: Almond Tofu & the Cloud-Sorting Job", "newSlug": "almond-tofu-and-the-cloud-sorting-job", "mainCharacter": "Xìngrén Dòufu (Almond Tofu) — a soft, pale, jiggly almond pudding who is a worrier about order and neatness", "setting": "A misty mountain teahouse perched in the clouds above Maokong", "theme": "Not everything needs to be tidy to be lovely", "spotlightTerm": "雲", "spotlightRomanization": "yún", "spotlightMeaning": "cloud", "premise": "Fussy Almond Tofu is hired to sort the teahouse's drifting clouds into neat fluffy rows for the view, but the clouds keep blending and swirling no matter how hard he tidies. He learns that the messiest, mingled cloud-sea is the most beautiful sight of all, and that some lovely things can't — and shouldn't — be kept in tidy lines.", "arc": "Almond Tofu accepts the impossible job of arranging the clouds -> he frets and herds them into rows that instantly drift apart -> mounting frustration and very silly cloud-wrangling mishaps -> a wise old teapot shows him the wild, swirling cloud-sea at sunset -> he lets go of tidiness and finally just enjoys the gloriously messy view.", "reason": "Chosen over canonical #18 and #30 (kept Sesame Ball stories) because #73 was a third 'bold Sesame Ball rolls into a daring physical feat then helps a rival' tournament. Switched to a brand-new soft character (Almond Tofu), a gentle cloud-sorting/whimsy plot with no rolling or racing, and a fresh let-go-of-tidiness theme distinct from the bravery-needs-heart lessons.", "collection": "taiwan", "path": "stories/73-almond-tofu-and-the-cloud-sorting-job.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 52, "oldTitle": "Story 52: Egg Waffle & the New Year's Eve Countdown", "newTitle": "Story 52: Turnip Cake & the Lucky-Word Banner", "newSlug": "turnip-cake-and-the-lucky-word-banner", "mainCharacter": "Cài Tóu Guǒ (Turnip/Radish Cake) — a humble, steamy, square savory cake, shy with words", "setting": "A family kitchen and front doorway during Lunar New Year's Eve preparations", "theme": "A wish written for your home is a wish for everyone in it", "spotlightTerm": "春聯", "spotlightRomanization": "chūnlián", "spotlightMeaning": "Spring Festival couplet banners", "premise": "On New Year's Eve, shy Turnip Cake is asked to write the lucky red banner for the door but freezes, afraid his clumsy brushstrokes will jinx the whole year. He discovers the banner isn't about perfect calligraphy — it's about naming the hopes you hold for the people inside, and his wobbly, heartfelt characters become the warmest welcome on the street.", "arc": "Turnip Cake is handed the brush for the all-important door banner and panics -> he practices and smudges and crumples sheet after sheet -> an elder reminds him a couplet is a wish, not a test -> he writes simple, honest words of warmth for his household -> neighbors stop to admire the heartfelt banner as the new year arrives.", "reason": "Chosen over canonical #16 (Night Market Showdown, kept) because #52 repeated the 'showman Egg Waffle's solo act flops, joy is found shoulder-to-shoulder' beat already in #16. Switched to a new character (Turnip Cake), a calligraphy-banner New Year activity, and a distinct theme about written wishes for one's home rather than performing-for-shared-joy.", "collection": "taiwan", "path": "stories/52-turnip-cake-and-the-lucky-word-banner.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 70, "oldTitle": "Story 70: Grass Jelly & the Cool Autumn Tea Hour", "newTitle": "Story 70: Pearl Barley & the Counting-Stars Sleepover", "newSlug": "pearl-barley-and-the-counting-stars-sleepover", "mainCharacter": "Yìrén (Pearl Barley / Job's Tears) — small, pale, pearly grains who travel as a chattery cluster", "setting": "A rooftop sleepover under the autumn sky in a quiet riverside town", "theme": "You don't have to fill every silence — some quiet is for wondering", "spotlightTerm": "星星", "spotlightRomanization": "xīngxing", "spotlightMeaning": "stars", "premise": "The Pearl Barley grains never stop chattering, and at the rooftop sleepover their nonstop talking keeps everyone awake. One grain learns that when you finally hush and look up, the quiet between words is where the biggest, most wonderful thoughts have room to grow — and counting stars together in silence is its own kind of conversation.", "arc": "The Pearl Barley cluster talks over everyone at the sleepover, nobody can sleep -> their endless chatter even drowns out a shy friend's wish to share something -> a gentle nudge to just look up at the sky -> they fall quiet and discover the awe of the silent star-filled night -> they learn that companionable quiet can say more than chatter.", "reason": "Chosen over canonical #5 (Cool Shadow, kept) because #70 was another 'calm Grass Jelly soothes an over-excited crowd, being still feels as good as bouncing' story. Switched to a new under-used character (Pearl Barley), a stargazing sleepover plot, and a distinct theme about the value of quiet wonder rather than 'calm is what helps everyone' — and the #90 Blackout (ensemble light story) was left intact as distinct.", "collection": "taiwan", "path": "stories/70-pearl-barley-and-the-counting-stars-sleepover.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 88, "oldTitle": "Story 88: Red Bean & Grandma's Kitchen", "newTitle": "Story 88: Peanut Brittle & the Stuck-Together Day", "newSlug": "peanut-brittle-and-the-stuck-together-day", "mainCharacter": "Huāshēng Táng (Peanut Brittle) — a crunchy, golden, glued-together slab of candied peanuts, loud and busy", "setting": "A sunny candy-maker's workshop on a humid summer afternoon", "theme": "Slowing down lets you notice who's right beside you", "spotlightTerm": "慢慢來", "spotlightRomanization": "mànman lái", "spotlightMeaning": "take it slow / no rush", "premise": "Busy, always-rushing Peanut Brittle prides himself on getting everything done fast, until a sticky-humid day makes the whole workshop go gooey and slow. Forced to wait for the candy to set, he finally sits still long enough to really talk to the quiet little peanut who has been stuck beside him the whole time — and finds his oldest friend was right there all along.", "arc": "Peanut Brittle zooms through chores, brushing past everyone -> the humid day softens the candy so nothing can be hurried -> he fidgets, impatient, with nothing to do but wait -> stuck beside a shy peanut he'd never really noticed, he finally chats and listens -> he learns slowing down let him find a friend he'd been rushing right past.", "reason": "Chosen over canonical #9 and #32 (kept Red Bean warmth stories) because #88 repeated the 'nurturing Red Bean's slow soup teaches a hurried snack that love can't be rushed' arc. Switched to a new character (Peanut Brittle), a candy-workshop setting, and a theme about slowing down to notice a friend beside you (not nurturing/feeding others). Left #66 (spring-waking) intact as distinct.", "collection": "taiwan", "path": "stories/88-peanut-brittle-and-the-stuck-together-day.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 89, "oldTitle": "Story 89: Coconut Jelly & the Lazy River Float", "newTitle": "Story 89: Sun Cake & the Sundial Garden", "newSlug": "sun-cake-and-the-sundial-garden", "mainCharacter": "Tàiyáng Bǐng (Sun Cake) — a flaky, golden, layered Taichung pastry with a warm maltose heart", "setting": "An old walled garden in Taichung with a moss-covered sundial", "theme": "There's a right moment for everything — and waiting for it is a skill", "spotlightTerm": "時間", "spotlightRomanization": "shíjiān", "spotlightMeaning": "time", "premise": "Sun Cake wants the garden's rare night-blooming flower to open NOW so he can show his visiting friends, and keeps trying to pry the petals apart. The old sundial teaches him to read the slow turning of the day and wait for exactly the right moment — and when the flower finally unfurls on its own at dusk, the patience makes it ten times more magical.", "arc": "Sun Cake brags he'll show off the famous night-blooming flower -> he tugs and pokes, but the bud stays stubbornly shut -> the sundial shows him how light moves and that timing matters -> he waits, restless, watching the shadow creep -> at the perfect dusk moment the flower bursts open, and the wait makes it unforgettable.", "reason": "Chosen over canonical #15 (Beach Party, kept) because #89 repeated the 'chill Coconut Jelly teaches a rushing friend to slow down and drift' go-with-the-flow lesson. Switched to a new character (Sun Cake), a sundial-and-flower garden plot, and a distinct theme about timing/waiting for the right moment (active patience) rather than passively going with the flow. Left #62 (Kenting rescue subversion) intact.", "collection": "taiwan", "path": "stories/89-sun-cake-and-the-sundial-garden.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 69, "oldTitle": "Story 69: Starfruit & the Autumn Meteor Shower", "newTitle": "Story 69: Candied Tomato & the Worry-Jar Wishing Well", "newSlug": "candied-tomato-and-the-worry-jar-wishing-well", "mainCharacter": "Niúfān Qié (Plum-Powder Candied Tomato) — a glossy red candied cherry-tomato-on-a-stick, sweet-tart and earnest", "setting": "A village wishing well beside a banyan tree at twilight", "theme": "Letting a worry go can make room for someone else's hope", "spotlightTerm": "願望", "spotlightRomanization": "yuànwàng", "spotlightMeaning": "wish", "premise": "Candied Tomato keeps every single one of her worries bottled in little jars, terrified to let them go. At the old wishing well she learns that you can't toss in a hopeful coin if both hands are full of worry-jars — so she gently sets her worries down, frees her hands, and helps a frightened friend cast the very first wish of their life.", "arc": "Candied Tomato lugs an armful of worry-jars to the wishing well -> she can't make a wish because her hands are too full -> a small friend is too scared to wish at all -> she sets her jars down on the well's edge, freeing her hands -> she helps the friend toss the first coin, and discovers letting worries go made room for someone else's hope.", "reason": "Chosen over canonical #19 (Five-Pointed Wish, kept) because #69 repeated the 'dreamy Starfruit gives away her wishes to friends who need them more' lesson. Switched to a new character (Candied Tomato), a worry-jar/wishing-well plot, and a distinct theme about releasing one's own worries to make space for another's hope — not 'a wish shared shines farther.' Left #58 (Earth God temple wishes) intact as a different protagonist.", "collection": "taiwan", "path": "stories/69-candied-tomato-and-the-worry-jar-wishing-well.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 64, "oldTitle": "Story 64: Pineapple Cake & the Harbor Gift", "newTitle": "Story 64: Nougat & the Borrowed-Umbrella Chain", "newSlug": "nougat-and-the-borrowed-umbrella-chain", "mainCharacter": "Niúgá Táng (Milk Nougat) — a chewy, milky-white candy studded with nuts, cheerful and a bit forgetful", "setting": "A rainy shopping street with a long covered arcade in Jiufen", "theme": "A small kindness passed on travels farther than one kept", "spotlightTerm": "雨傘", "spotlightRomanization": "yǔsǎn", "spotlightMeaning": "umbrella", "premise": "Caught in a downpour, Nougat is lent an umbrella by a stranger who says only 'pass it on when you can.' Instead of keeping the cozy umbrella, Nougat starts a chain of lending it down the rainy street, and by nightfall a single borrowed umbrella has kept a dozen soggy snacks dry — proving a kindness shared keeps spreading long after you let it go.", "arc": "Nougat is soaked and shivering until a stranger lends an umbrella with one rule: pass it on -> he's tempted to keep it dry and warm -> he spots someone wetter than him and hands it over -> the umbrella travels snack to snack down the arcade -> by night it has sheltered the whole street, and the kindness loops back to Nougat himself.", "reason": "Chosen over canonical #6 (Golden Gift, kept) because #64 repeated the 'proud Pineapple Cake fusses over wrapping a gift, learns the heartfelt thing inside matters most' generosity arc. Switched to a new character (Milk Nougat), a pay-it-forward umbrella-chain plot, and a distinct theme about kindness passed along (not the thoughtful-gift-wrapping lesson).", "collection": "taiwan", "path": "stories/64-nougat-and-the-borrowed-umbrella-chain.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 85, "oldTitle": "Story 85: Mochi & the Stretchiest Group Hug", "newTitle": "Story 85: Cuttlefish Ball & the Tangled Lantern Strings", "newSlug": "cuttlefish-ball-and-the-tangled-lantern-strings", "mainCharacter": "Huāzhī Wán (Cuttlefish Ball) — a bouncy, springy seafood ball on a skewer, eager and a little frazzled", "setting": "A temple courtyard the morning the festival lanterns must be hung", "theme": "Asking for help untangles what you can't sort out alone", "spotlightTerm": "幫忙", "spotlightRomanization": "bāngmáng", "spotlightMeaning": "to help", "premise": "Determined to hang all the festival lanterns himself, springy Cuttlefish Ball bounces around tying strings until he's hopelessly tangled in a giant knot of lantern cords. Too proud to call out at first, he finally squeaks for help — and learns that the knot loosens in minutes when many hands each take one string, while one frazzled snack could never undo it alone.", "arc": "Cuttlefish Ball insists on hanging every lantern by himself before the festival -> he bounces and ties until he's bound up in a snarl of strings -> he struggles silently, embarrassed to ask -> he finally calls 'bāngmáng!' and friends each grab a strand -> the knot falls away, lanterns rise, and he learns help shared lightens any tangle.", "reason": "Chosen over canonical #4 (Stretchy Escape, kept) because #85 repeated the 'clingy stretchy Mochi strains to hold/gather everyone, a hug grows when passed along' lesson. Switched to a brand-new character (Cuttlefish Ball) — also de-duplicating the two Mochi entries flagged in this batch — with a lantern-hanging plot and a distinct asking-for-help theme rather than the sharing-a-hug lesson.", "collection": "taiwan", "path": "stories/85-cuttlefish-ball-and-the-tangled-lantern-strings.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 37, "oldTitle": "Story 37: Stinky Tofu & the Best-Smell Contest", "newTitle": "Story 37: Stinky Tofu & the Lights-Out Hide-and-Seek", "newSlug": "stinky-tofu-and-the-lights-out-hide-and-seek", "mainCharacter": "Chòu Chòu (Stinky Tofu) — the bold, pungent fried-tofu cube", "setting": "A maze-like old shophouse alley during a power-out game of hide-and-seek", "theme": "The very thing you'd hide can be what helps everyone find each other", "spotlightTerm": "捉迷藏", "spotlightRomanization": "zhuō mícáng", "spotlightMeaning": "hide-and-seek", "premise": "During a lights-out game of hide-and-seek in the twisty alleys, the little snacks get hopelessly lost in the dark. Chòu Chòu, who usually tries to hide his powerful aroma, realizes his unmistakable smell is the one thing that can guide every lost player back to the group — and for once he proudly lets his scent lead the way home.", "arc": "The snacks play hide-and-seek as the lights go out, and several get lost in the dark maze of alleys -> Chòu Chòu instinctively tries to tuck his smell away as always -> the lost players can't see a thing and start to worry -> he realizes his scent is a homing beacon and stops hiding it -> he leads everyone safely back, his 'flaw' the hero of the night.", "reason": "Kept canonical #22 (Stinky Tofu Demon) and chose to rewrite #37 because both ran the identical 'mocked-for-smell tofu learns his scent wins everyone over' best-smell-contest arc. Kept the same character per the cluster's core (it's his defining trait) but gave it a wholly different plot — a dark hide-and-seek where his smell is a navigation beacon — and a distinct theme about a hidden trait guiding others home, not winning a contest. Left #75 (Passion Fruit's sour-dare derby) intact.", "collection": "taiwan", "path": "stories/37-stinky-tofu-and-the-lights-out-hide-and-seek.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 74, "oldTitle": "Story 74: Popcorn Chicken & the Claw Machine Rescue", "newTitle": "Story 74: Tempura Fishcake & the Hot-Spring Egg Race", "newSlug": "tempura-fishcake-and-the-hot-spring-egg-race", "mainCharacter": "Tián Bù Lǎ (Taiwanese Tianbula / fishcake) — a chewy, ridged, golden fried fishcake who is patient and methodical", "setting": "A volcanic hot-spring village in Beitou where eggs cook in the steaming pools", "theme": "Doing one careful thing well beats doing ten things in a hurry", "spotlightTerm": "溫泉", "spotlightRomanization": "wēnquán", "spotlightMeaning": "hot spring", "premise": "When a crowd of snacks rushes to soft-boil their eggs in the famous hot springs all at once, they snatch them out too early and end up with a runny mess. Methodical Tianbula shows them that the trick isn't speed — it's lowering one egg gently, timing it just right, and waiting patiently for the perfect, jiggly result everyone's been hurrying past.", "arc": "Everyone races to dunk eggs in the steaming pools to be first to eat -> they yank them out too soon and grumble at the gloppy results -> impatient retries make a bigger mess -> Tianbula calmly demonstrates careful timing with a single egg -> the crowd slows down, copies him, and shares a basket of perfect spring-cooked eggs.", "reason": "Kept #39 (Runaway Giggle) as the canonical Popcorn Chicken nugget-gather story and rewrote #74 because both used the same 'Kǎ Kǎ crew races to rescue/regather a scattered or trapped nugget before a closing deadline.' Switched to a new character (Tianbula fishcake), a hot-spring egg-cooking plot, and a distinct careful-patience-over-haste theme — no rescue or deadline, no popcorn-chicken crew.", "collection": "taiwan", "path": "stories/74-tempura-fishcake-and-the-hot-spring-egg-race.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 34, "oldTitle": "Story 34: Soup Dumpling & the Eighteen Folds", "newTitle": "Story 34: Soup Dumpling & the Steamer-Stack Sleepover", "newSlug": "soup-dumpling-and-the-steamer-stack-sleepover", "mainCharacter": "Xiǎo Lóng (Soup Dumpling)", "setting": "A towering stack of bamboo steamer baskets at a dim-sum house, late at night", "theme": "The top spot isn't always the best spot", "spotlightTerm": "蒸籠", "spotlightRomanization": "zhēnglóng", "spotlightMeaning": "bamboo steamer basket", "premise": "Xiǎo Lóng is convinced the only place worth being is the very top steamer basket, where everyone gets served first. He scrambles and squeezes his way up, only to find the top is drafty and lonely — while the cozy warm middle baskets, where the steam gathers and friends are packed close, were the best spot all along.", "arc": "Xiǎo Lóng elbows his way toward the top steamer basket, sure it's the place to be -> he reaches the top and finds it cold, wobbly, and lonely up there -> he watches the warm, giggly middle baskets below with envy -> he climbs back down into the snug middle -> he learns the cozy crowded middle, not the lofty top, is where the good stuff is.", "reason": "Kept canonical #17 (Pudding/Wobble Contest) and rewrote #34 because its original 'perfectionist frets over one crooked pleat, learns the flaw is his charming signature' shared the authenticity-beats-perfection arc with #17. Kept the character but gave a new climbing/steamer-stack plot and a distinct theme about the cozy middle beating the lofty top, with no perfection-flaw lesson.", "collection": "taiwan", "path": "stories/34-soup-dumpling-and-the-steamer-stack-sleepover.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 83, "oldTitle": "Story 83: Brown Sugar & the Tiger-Stripe Masterpiece", "newTitle": "Story 83: Brown Sugar & the Slow-Drip Mooncake Clock", "newSlug": "brown-sugar-and-the-slow-drip-mooncake-clock", "mainCharacter": "Hēi Táng (Brown Sugar)", "setting": "A quiet teahouse with an antique water-clock the night before a festival", "theme": "Some sweetness only arrives if you don't rush it", "spotlightTerm": "慢", "spotlightRomanization": "màn", "spotlightMeaning": "slow", "premise": "Theatrical Brown Sugar wants his famous syrup ready in a flash for the festival crowd, but the old teahouse water-clock insists good brown-sugar syrup must drip and thicken slowly, drop by drop, all night. As he waits, he learns that the deep, dark, glorious flavor everyone loves is the gift of patience — and rushing would have ruined it.", "arc": "Brown Sugar tries to whip up his syrup fast for tomorrow's crowd -> the rushed batch is thin and bland -> the antique water-clock shows him syrup must thicken slowly overnight -> he frets but lets it drip drop by drop while he waits -> by dawn the syrup is rich and deep, and he savors that the best flavor took all night.", "reason": "Kept #76 (Bubble-Tea Shake-Off) as the canonical collaboration/'make room for others' story and rewrote #83 because both had Brown Sugar + Boba learning that the best cup is a collaboration. Kept the character but switched to a solo slow-syrup-making plot with a water-clock, and a distinct patience-for-flavor theme rather than the share-the-spotlight collaboration lesson. Left #35 (Scallion Pancake) intact as a distinct character pairing.", "collection": "taiwan", "path": "stories/83-brown-sugar-and-the-slow-drip-mooncake-clock.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 86, "oldTitle": "Story 86: Taro & the Purple Sunset Balloon", "newTitle": "Story 86: Sago Pudding & the Sandcastle That Wouldn't Stay", "newSlug": "sago-pudding-and-the-sandcastle-that-wouldnt-stay", "mainCharacter": "Xī Mǐ Lù (Sago Pudding) — a cool, milky pudding full of tiny translucent sago pearls, gentle and accepting", "setting": "A breezy white-sand beach on Penghu island at low tide", "theme": "It's okay when something beautiful doesn't last", "spotlightTerm": "沙堡", "spotlightRomanization": "shābǎo", "spotlightMeaning": "sandcastle", "premise": "Sago Pudding helps a heartbroken little friend build the grandest sandcastle on the beach, only for the tide to wash it away. Instead of sadness, gentle Sago Pudding shows that the fun was in the building, the castle lives on in their memory, and tomorrow's beach is a fresh blank canvas — teaching that some lovely things are meant to be temporary and that's exactly what makes them special.", "arc": "Sago Pudding and a friend build an elaborate sandcastle together -> the tide creeps in and the friend panics to save it -> the waves wash the castle flat -> the friend is crushed, but Sago Pudding reframes the joy of building and remembering -> they laugh, scoop fresh sand, and plan tomorrow's castle, at peace with impermanence.", "reason": "Kept #59 (Southern Sugar Fields) as the canonical patient-Taro-teaches-patience story and rewrote #86 because it was a second patient-Taro 'rise slowly and savor it' lesson. Switched to a brand-new character (Sago Pudding), a sandcastle-and-tide beach plot, and a distinct theme about accepting impermanence rather than patience-yields-sweetness. (Care taken to differ from canonical #7's impermanence story, which is about a character fearing their own melting — here it's making peace with a shared creation washing away.) Left #57 (Tea Leaf) intact as a different character.", "collection": "taiwan", "path": "stories/86-sago-pudding-and-the-sandcastle-that-wouldnt-stay.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 96, "oldTitle": "Story 96: Mochi & the Moonbeam Invitations", "newTitle": "Story 96: Lantern Squid & the Tide-Chart Crossing", "newSlug": "lantern-squid-and-the-tide-chart-crossing", "mainCharacter": "Yóu Yú Gēng (Squid Thick-Soup) — a savory, peppery squid soup in a bowl, a practical seafarer type", "setting": "The fishing harbor of an offshore island, planning the boat trip to the mainland reunion", "theme": "Knowing the right moment to go is its own kind of wisdom", "spotlightTerm": "潮汐", "spotlightRomanization": "cháoxī", "spotlightMeaning": "the tides", "premise": "The far-flung island snacks are desperate to set off for the grand reunion right away, but the boat can only cross safely at high tide. Practical Squid Soup reads the old tide-chart and convinces the eager crowd to wait for the perfect moment — and when the tide finally lifts the boat, their patience carries them across smoothly, arriving in time and all in one happy piece.", "arc": "The island snacks pack up, frantic to leave immediately for the reunion -> Squid Soup warns the harbor is too shallow until high tide -> the impatient crowd grumbles and nearly launches anyway -> they wait, watching the water rise on the tide-chart -> at high tide the boat glides out easily, and they reach the mainland reunion safe and joyful.", "reason": "Kept #92 (Letter to Every Friend) as the canonical reaching-out/invitation story and rewrote #96 because 'Mochi sends glowing invitations so nobody is left out' was the same deliver-invitations-to-everyone beat. Switched to a new character (Squid Soup) and a tide-timing sea-crossing plot, with a distinct theme about knowing the right moment to set out — a journey-logistics story rather than an invitation-delivery one. (De-dupes the second Mochi entry too.) Left #94 (Tea Egg's map of paths) intact as a navigation/guiding story rather than invitations.", "collection": "taiwan", "path": "stories/96-lantern-squid-and-the-tide-chart-crossing.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 61, "oldTitle": "Story 61: Sweet Potato & the East Coast Cliffs", "newTitle": "Story 61: Sweet Potato & the Lantern-Float River Night", "newSlug": "sweet-potato-and-the-lantern-float-river-night", "mainCharacter": "Dìguā (Sweet Potato)", "setting": "A slow river at night during a floating water-lantern ceremony in eastern Taiwan", "theme": "Letting go is sometimes braver than holding on", "spotlightTerm": "放手", "spotlightRomanization": "fàngshǒu", "spotlightMeaning": "to let go", "premise": "At the river's floating-lantern night, a little snack clutches a worry he can't bear to release onto the water. Street-smart Sweet Potato — who once buried himself deep in the earth and had to let the farmer dig him up — gently shares that letting a thing drift away can be the bravest move of all, and together they set the worry-lantern gently onto the current.", "arc": "A small friend grips his worry-lantern, unable to set it on the river -> Sweet Potato notices and sits beside him on the bank -> Sweet Potato tells of being dug from the dark earth and learning to let go -> they count to three and release the lantern together -> they watch it join a river of golden lights drifting peacefully downstream.", "reason": "Kept canonical #14 (Underground Adventure) and rewrote #61 because both had street-smart Sweet Potato guiding a timid companion through a rugged landscape with the same humble-inner-worth/hidden-treasure lesson. Kept the character (his earthy grounding suits the new mentor role) but switched to a tranquil river-lantern setting and a wholly new theme about the bravery of letting go — no rugged-hike adventure or inner-worth-beats-shine moral.", "collection": "taiwan", "path": "stories/61-sweet-potato-and-the-lantern-float-river-night.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 81, "oldTitle": "Story 81: Lychee & the Summer Fruit Ball", "newTitle": "Story 81: Lychee & the Hand-Me-Down Fan", "newSlug": "lychee-and-the-hand-me-down-fan", "mainCharacter": "Lìzhī (Lychee)", "setting": "A grandmother fruit-seller's shaded stall at a sweltering traditional market", "theme": "The oldest, plainest things often hold the most love", "spotlightTerm": "扇子", "spotlightRomanization": "shànzi", "spotlightMeaning": "fan", "premise": "Fancy Lychee is mortified that her elegant new silk fan tears on the hottest day, and turns up her nose at the worn, faded paper fan an old fruit-seller offers her. But the shabby little fan turns out to have been hand-painted with love and to cool better than any fancy one — teaching Lychee that worth and beauty hide in well-loved old things, not just new finery.", "arc": "Lychee shows off her dazzling new silk fan at the market -> the delicate fan rips in the heat and she's left fanning frantically -> a kindly old seller offers a battered, faded paper fan -> Lychee reluctantly accepts, then discovers it's lovingly hand-painted and cools beautifully -> she treasures the humble heirloom and thanks the seller warmly.", "reason": "Kept canonical #12 (Forbidden Tree) and rewrote #81 because both ran vain Lychee's same vanity-to-humility 'true elegance is valuing the humble/welcoming everyone' arc. Kept the character but switched to a hand-me-down-fan plot and sharpened the theme specifically to worn old things holding love (an heirloom-appreciation angle) rather than the hostess-welcomes-overlooked-guests lesson, keeping it distinct from #12's don't-judge-by-appearance moral.", "collection": "taiwan", "path": "stories/81-lychee-and-the-hand-me-down-fan.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 71, "oldTitle": "Story 71: Tangyuan & the First Snow on Hehuan Mountain", "newTitle": "Story 71: Hot Pot Mochi & the Frozen-Lake Skating Wobble", "newSlug": "hot-pot-mochi-and-the-frozen-lake-skating-wobble", "mainCharacter": "Shāo Má Shǔ (Toasted Mochi) — a puffy grilled mochi dusted in soybean powder, eager but unsteady", "setting": "A rare frozen alpine lake high in the mountains on a crisp winter day", "theme": "Falling down is just part of learning something new", "spotlightTerm": "滑冰", "spotlightRomanization": "huábīng", "spotlightMeaning": "ice skating", "premise": "On the rare day the high mountain lake freezes, Toasted Mochi wants to ice-skate gracefully on his very first try and is crushed every time he flops onto his squishy bottom. With friends cheering each tumble, he learns that every fall is a step toward gliding — and by sunset his wobbly, giggly skating has turned into the happiest, most fearless slide on the whole lake.", "arc": "Toasted Mochi straps on skates expecting instant grace and immediately flops -> embarrassed by fall after fall, he wants to quit -> friends cheer his tumbles instead of laughing at them -> he keeps trying, falling, and getting up, improving bit by bit -> by dusk he glides freely, proud that every fall taught him to skate.", "reason": "Kept canonical #25 (Demon King's Midnight Snack) and rewrote #71 because both turned the coldest night into a Tangyuan-led shared warm-soup gathering with the 'warmth is carried/shared' lesson. Switched to a new character (Toasted Mochi), an ice-skating-in-the-cold plot, and a brand-new theme about persevering through falls when learning — no warm-soup-gathering or warmth-is-shared moral, and distinct from the wobble/imperfection themes in #17/#31.", "collection": "taiwan", "path": "stories/71-hot-pot-mochi-and-the-frozen-lake-skating-wobble.md", "spotlightLabel": "Mandarin Spotlight"}, {"number": 6, "oldTitle": "Niu the Coconut and the Tough Shell", "newTitle": "Saimin Sam and the Great Noodle Knot", "newSlug": "saimin-sam-and-the-great-noodle-knot", "mainCharacter": "Saimin Sam (a steaming bowl of saimin noodle soup)", "setting": "A steamy little saimin stand near a Honolulu plantation town, on the night of a noodle slurp-off", "theme": "Owning a mistake makes you bigger, not smaller.", "spotlightTerm": "kala mai", "spotlightRomanization": "KAH-lah MY", "spotlightMeaning": "excuse me / I'm sorry", "premise": "Saimin Sam can't stop swishing his noodles to make them 'perfect' and swirls them into one giant hopeless knot right before the Great Slurp-Off. Tempted to blame the wind, he instead owns the mistake out loud, and the whole stand of soup bowls rallies to untangle his noodles, laughing with him.", "arc": "Pride (best slurper) -> self-made disaster (the knot) -> the slippery temptation to lie and blame the wind -> the brave choice to confess -> friends respond with kindness and help -> realizing honesty made him feel bigger and warmer, not smaller.", "reason": "Story 6 was a near-identical 'guard the sweet inside, then learn to open up and share' arc to canonical Story 3 (Malia). Kept Malia #3 unchanged and fully replaced #6: a brand-new under-used food character (saimin, not the over-used coconut), a totally different plot (a noodle-knot slurp-off mishap), and a distinct emotional lesson about honesty and accountability rather than sharing. Avoids overlap with 'different is special' (#26) and 'true voice' (#23).", "collection": "hawaii", "path": "hawaii/stories/06-saimin-sam-and-the-great-noodle-knot.md", "spotlightLabel": "Hawaiian Spotlight"}, {"number": 47, "oldTitle": "The Boba Friends Come to Visit", "newTitle": "Manapua Mano and the Quietest Question", "newSlug": "manapua-mano-and-the-quietest-question", "mainCharacter": "Manapua Mano (a big soft steamed bun)", "setting": "A backyard welcome-table in Waikiki for the Taiwan dessert visitors (Boba, Mango, Yeguo)", "theme": "A good host listens to learn, instead of showing off.", "spotlightTerm": "hoaloha", "spotlightRomanization": "hoh-ah-LOH-hah", "spotlightMeaning": "friend", "premise": "Manapua plans the BIGGEST, loudest welcome for the visiting Taiwan snacks (booming drums, spicy dares, giant waves) and overwhelms his tired, shy guests. When he finally goes quiet, he realizes he has shown off all day without ever asking them a single question, and learns that real welcome comes from listening, not performing.", "arc": "Over-eager host trying to impress with bigness and noise -> guests shrink and nearly cry -> Manapua falls silent and overhears that their home-welcome is small, cozy, and full of questions -> he asks his first gentle question -> warm afternoon of mutual listening -> realizes the quietest question was the warmest welcome.", "reason": "Story 47 duplicated canonical Story 1's (Dani) 'warm welcome makes instant family / make room for the newcomer' arc, and even reused Dani as lead. Kept Dani #1 unchanged. Switched the lead to under-used Manapua Mano, kept the required Boba crossover guests, and gave it a genuinely different lesson about humility and listening (host who must stop showing off) rather than 'a warm hello starts a friendship' or 'newcomers are instant family.'", "collection": "hawaii", "path": "hawaii/stories/47-manapua-mano-and-the-quietest-question.md", "spotlightLabel": "Hawaiian Spotlight"}, {"number": 48, "oldTitle": "The Great Island-Hopping Race", "newTitle": "Kamaron the Garlic Shrimp and the Cheering Truck", "newSlug": "kamaron-the-garlic-shrimp-and-the-cheering-truck", "mainCharacter": "Kamaron the Garlic Shrimp", "setting": "A North Shore beach-games day beside the famous garlic-shrimp trucks", "theme": "Cheering someone else across the finish line is its own kind of winning.", "spotlightTerm": "ho'omaika'i", "spotlightRomanization": "hoh-oh-my-KAH-ee", "spotlightMeaning": "to congratulate / to praise", "premise": "Kamaron is the fastest snack on the beach and wins every single race at the North Shore Beach Games, but each lonely victory feels emptier while the whole crowd roars instead for whoever finishes last. He discovers that the joy was never in finishing first, and chooses to become his friends' loudest cheerleader in the final relay.", "arc": "Fastest snack who wins everything -> notices the biggest cheers always go to the LAST finisher, not him -> feels lonely winning alone -> Musubi Manu points out he watches the finish line while everyone else watches each other -> in the final race he gives up winning to cheer his friends across -> ends up in the warm middle of the pile, having done 'the winning that counts.'", "reason": "Story 48 was flagged in two clusters: it repeated canonical Story 5's (Poke Pua) perfectionist arc AND Story 46's (Lilikoi Lani) 'going it alone fails, joy multiplies together' lesson, with Poke Pua learning 'winning together beats winning alone' a second time. Kept Poke Pua #5 and Lilikoi Lani #46 unchanged. Replaced the lead with a brand-new under-used character (garlic shrimp), changed the plot to a non-relay beach-games day, and shifted the lesson to good-sportsmanship and generously cheering others on, which is distinct from 'winning together' (#48 old), 'done with love beats perfect' (#5), 'joy multiplies when community joins' (#46), and 'falling is part of learning' (#28).", "collection": "hawaii", "path": "hawaii/stories/48-kamaron-the-garlic-shrimp-and-the-cheering-truck.md", "spotlightLabel": "Hawaiian Spotlight"}, {"number": 24, "oldTitle": "The Cloud Forest Cheese and Honey", "newTitle": "Chorreado and the Lost-and-Found Spoon", "newSlug": "chorreado-and-the-lost-and-found-spoon", "mainCharacter": "Chorreado the Corn Pancake", "setting": "A misty Monteverde cloud-forest kitchen at first light, where the morning natilla and breakfast things live on a wooden shelf", "theme": "Asking for help is a brave thing, not a weak one.", "spotlightTerm": "ayuda", "spotlightRomanization": "ah-YOO-dah", "spotlightMeaning": "help", "premise": "Chorreado, a warm little corn pancake, has lost the one wooden spoon that flips him, and he is far too proud to admit it because everyone thinks he is the most independent breakfast on the shelf. He spends the foggy morning trying to flip himself in increasingly silly ways (rolling, bouncing, asking the fog to gust under him) and keeps landing splat. Only when he finally squeaks out 'ayuda?' do the natilla pot, a curious cloud-forest mouse, and Don Cafe come together to find the spoon tucked under a coffee sack and flip him golden — and he learns that the bravest cooks ask for a hand.", "arc": "Proud self-reliance to comic repeated failures to a vulnerable request for help to joyful rescue and a new understanding that needing others is part of belonging.", "reason": "Cluster 2 [high]: nearly identical 'opposites/different foods are better together, resolved by a peacemaker' arc shared with The Casado That Couldn't Agree (#6), which is the canonical version and is kept unchanged. This was the lower-priority duplicate of the two flagged, so it is rewritten. It now uses a brand-new under-used character (Chorreado the corn pancake) instead of Lala, drops the 'two foods argue over who's tastier / mediator unites them' plot entirely, and teaches an asking-for-help lesson found nowhere else in the collection.", "collection": "costa-rica", "path": "costa-rica/stories/24-chorreado-and-the-lost-and-found-spoon.md", "spotlightLabel": "Spanish Spotlight"}, {"number": 23, "oldTitle": "The Coffee Pickers' Song", "newTitle": "Cas the Sourpuss and the Sweetest Surprise", "newSlug": "cas-the-sourpuss-and-the-sweetest-surprise", "mainCharacter": "Cas the Sour Guava", "setting": "A sunny fruit-stand corner of Pura Vida Town where fresco drinks are blended", "theme": "Being a little different (even a little sour) is exactly what makes you special.", "spotlightTerm": "fresco", "spotlightRomanization": "FRES-koh", "spotlightMeaning": "a fresh blended fruit drink", "premise": "Cas, a small puckery green guava, is sure nobody could ever love something so sour, so he hides at the back of the fruit basket while sweet mangoes and bananas get chosen for every fresco. When a too-sweet, sticky-hot afternoon leaves all the syrupy drinks tasting flat and cloying, the blender pitcher begs for just a splash of something bright — and Cas's puckery tang turns the dull fresco into the most refreshing, can't-stop-sipping drink the whole street has tasted. He discovers his sourness was never a flaw; it was the spark everything else was missing.", "arc": "Self-conscious hiding to a moment of being unexpectedly needed to delighted pride in his own zesty difference.", "reason": "Cluster 3 [med]: shared the mentor-coffee-bean-reassures-an-anxious-young-coffee-character setup and overlapping coffee-harvest setting with Don Cafe and the Slow Sunrise (#5), the lower-numbered canonical mentor story, which is kept. Rewriting this one fully removes the repeated coffee-mentor/anxious-young-bean arc by switching to a new under-used character (Cas the sour guava), a new fruit-stand setting, and a distinct 'your difference is your gift' lesson with no coffee mentor at all.", "collection": "costa-rica", "path": "costa-rica/stories/23-cas-the-sourpuss-and-the-sweetest-surprise.md", "spotlightLabel": "Spanish Spotlight"}, {"number": 36, "oldTitle": "Tamalita and the Christmas Tamale Night", "newTitle": "Pan Bon and the Christmas Eve Mix-Up", "newSlug": "pan-bon-and-the-christmas-eve-mix-up", "mainCharacter": "Pan Bon the Caribbean Sweet Bread", "setting": "A cozy Caribbean-coast home on Christmas Eve, with the oven warm and gifts waiting", "theme": "Owning up to a mistake mends things faster than hiding it.", "spotlightTerm": "perdon", "spotlightRomanization": "pehr-DOHN", "spotlightMeaning": "sorry / pardon", "premise": "Spicy-sweet Pan Bon is so excited for Christmas that he accidentally knocks the whole tray of carefully labeled gift-bundles off the table, jumbling every name tag so nobody knows which present is whose. Terrified of spoiling Navidad, he first tries to sneakily fix it and only makes the tangle worse. When he finally takes a deep breath and says 'perdon, it was me' to the gathered familia, everyone laughs warmly, turns the mix-up into a giggly guessing game, and the night becomes the most memorable Christmas yet — teaching Pan Bon that a brave 'sorry' is the best gift of all.", "arc": "Excitement to accidental mess to fearful covering-up to honest confession to relief, forgiveness, and a holiday made sweeter by the truth.", "reason": "Cluster 4 [med]: identical 'shy newcomer is gently welcomed and discovers they belong' arc shared with Olla de Carne (#22, kept as canonical) and the rewritten Snack Swap (#42); flagged as especially close to the helper-brings-in-a-shy-newcomer beat. Rewritten with a new under-used character (Pan Bon, a Caribbean sweet bread), keeping the warm Christmas-tamale-night holiday flavor of the slot but replacing the belonging plot entirely with an honesty-and-apology lesson that appears nowhere else.", "collection": "costa-rica", "path": "costa-rica/stories/36-pan-bon-and-the-christmas-eve-mix-up.md", "spotlightLabel": "Spanish Spotlight"}, {"number": 42, "oldTitle": "The School Recess Snack Swap", "newTitle": "Pejibaye and the Wobbly First Kick", "newSlug": "pejibaye-and-the-wobbly-first-kick", "mainCharacter": "Pejibaye the Peach-Palm Fruit", "setting": "A schoolyard at recreo where the kids are choosing teams for a quick futbol game", "theme": "Courage means being the first to try, even when your knees shake.", "spotlightTerm": "valiente", "spotlightRomanization": "bah-lee-EN-teh", "spotlightMeaning": "brave", "premise": "Round little Pejibaye has watched the recess futbol game from the wall every single day, longing to play but frozen by the thought of missing the ball in front of everyone. When the game needs one more player and nobody will volunteer to take the scary first kick-off, Pejibaye's heart pounds — and he rolls forward anyway, whispering 'valiente, valiente.' His first kick is a wobbly, sideways flub that sends the ball bonking off a tree and back to him for a lucky goal, and the whole yard cheers not for the goal but for the courage it took to go first.", "arc": "Longing-from-the-sidelines to trembling decision to act to a clumsy-but-brave first attempt to the discovery that courage matters more than getting it perfect.", "reason": "Cluster 4 [med]: this was one of the three near-identical 'shy newcomer welcomed, discovers they belong' stories (with Olla de Carne #22, kept canonical, and Tamalita #36), and was flagged as especially close to #36's helper-brings-in-the-shy-one beat. Rewritten with a new under-used character (Pejibaye the peach-palm fruit) and a distinct courage-to-go-first lesson set in a quick recess game, so it no longer repeats the belonging arc.", "collection": "costa-rica", "path": "costa-rica/stories/42-pejibaye-and-the-wobbly-first-kick.md", "spotlightLabel": "Spanish Spotlight"}, {"number": 34, "oldTitle": "The Crab Parade on the Shore", "newTitle": "Rondon and the Borrowed Pot", "newSlug": "rondon-and-the-borrowed-pot", "mainCharacter": "Rondon the Caribbean Coconut Stew", "setting": "A breezy Caribbean-coast beach kitchen at dusk where the big cooking pot is shared", "theme": "Letting go of a grudge makes room for friendship again.", "spotlightTerm": "amistad", "spotlightRomanization": "ah-mees-TAHD", "spotlightMeaning": "friendship", "premise": "Bubbly coconut stew Rondon has been quietly cross at the Pelican ever since the bird borrowed his big cooking pot and returned it dented. He simmers and sulks all afternoon, refusing to share the seaside supper. But when a sudden evening downpour leaves the whole beach hungry and cold, the dented pot turns out to be the only one wide enough to feed everyone — and the apologetic Pelican shows up with fresh fish to add. Rondon decides the warm meal matters more than the old dent, lets the grudge float out to sea, and the two stir up the coziest shared supper on the shore.", "arc": "Nursing a small resentment to stubborn sulking to a moment that needs everyone together to a chosen act of forgiveness and a restored, warmer friendship.", "reason": "Cluster 5 [high]: near-identical 'can't do the group movement, learns to be proud of own style, everyone joins in' arc shared with The Caribbean Coconut Dance (#28, kept canonical) and The Marimba Music Night (#39). Fully rewritten with a new under-used character (Rondon the Caribbean coconut stew), dropping the parade/marching-your-own-way plot for a forgiveness-and-letting-go-of-a-grudge lesson that exists nowhere else in the collection.", "collection": "costa-rica", "path": "costa-rica/stories/34-rondon-and-the-borrowed-pot.md", "spotlightLabel": "Spanish Spotlight"}, {"number": 39, "oldTitle": "The Marimba Music Night", "newTitle": "Agua Dulce and the Quiet Helper", "newSlug": "agua-dulce-and-the-quiet-helper", "mainCharacter": "Agua Dulce the Sugarcane Drink", "setting": "A festive town-square fiesta with a marimba band, food carts, and string lights", "theme": "The quiet helpers behind the fun deserve a thank-you too.", "spotlightTerm": "gracias", "spotlightRomanization": "GRAH-see-ahs", "spotlightMeaning": "thank you", "premise": "While everyone dances and feasts at the marimba fiesta, warm sweet Agua Dulce keeps the whole party going from the sidelines — refilling cups, soothing tired feet, warming up chilly dancers — yet no one notices the humble cup of sugarcane drink doing all the unglamorous work. When the fiesta suddenly droops because the dancers are exhausted and the band is parched, Agua Dulce quietly revives them all, and Don Cafe gently points out who's been holding the night together. The square stops to give Agua Dulce a great big 'gracias,' and Agua Dulce learns that being a quiet helper is its own special kind of shining.", "arc": "Cheerfully unnoticed background helping to a moment when the party would fail without that help to public, heartfelt gratitude and a gentle pride in quiet service.", "reason": "Cluster 5 [high]: same 'can't dance the right way, embarrassed, learns own breezy style is welcome, everyone joins in' beat as The Caribbean Coconut Dance (#28, kept canonical) and Crab Parade (#34). Rewritten with a new under-used character (Agua Dulce the sugarcane drink) in the same marimba-fiesta setting, but with a wholly different plot and a 'gratitude for the unsung helper' lesson not used elsewhere, removing the dance-your-own-way repetition.", "collection": "costa-rica", "path": "costa-rica/stories/39-agua-dulce-and-the-quiet-helper.md", "spotlightLabel": "Spanish Spotlight"}, {"number": 40, "oldTitle": "The Futbol Final Fiesta", "newTitle": "Churchill and the Half-Time Repair", "newSlug": "churchill-and-the-half-time-repair", "mainCharacter": "Churchill the Puntarenas Shaved-Ice Sundae", "setting": "A packed seaside Puntarenas living room during the big national futbol final", "theme": "When friends squabble, a peacemaker can mend things before the game even matters.", "spotlightTerm": "calma", "spotlightRomanization": "KAHL-mah", "spotlightMeaning": "calm / take it easy", "premise": "During the tense national futbol final, the snacks get so worked up that two old friends — a plantain chip and a bean dip — start a sharp argument over who jinxed the team, and the cozy watch-party turns frosty. Towering, syrup-topped Churchill, the famous Puntarenas shaved-ice sundae, glides in at half-time and instead of taking sides, cools everyone's tempers with a gentle 'calma, amigos,' helping each friend hear the other out. By the time the second half starts, the squabble is patched, and whatever the final score, the friends are watching shoulder to shoulder again.", "arc": "A heated watch-party squabble between friends to a calm peacemaker who refuses to take sides to listening, apology, and a mended friendship that outlasts the match.", "reason": "Cluster 7 [med]: delivered the same 'trying your best / sharing the fun matters more than winning' moral as The Pelican Fishing Contest (#29), the lower-numbered story, which is kept unchanged. Rewritten with a new under-used character (Churchill, the Puntarenas shaved-ice sundae) and a distinct conflict-resolution/peacemaking lesson about mending a friends' quarrel, so the win-or-lose moral is no longer repeated. (Also resolves its low-priority overlap with Coco and the Pacific Waves #26 in Cluster 6.)", "collection": "costa-rica", "path": "costa-rica/stories/40-churchill-and-the-half-time-repair.md", "spotlightLabel": "Spanish Spotlight"}, {"number": 58, "oldTitle": "Maru Matcha and the Zen Rock Garden", "newTitle": "Kompei and the Indigo Dye Workshop", "newSlug": "kompei-and-the-indigo-dye-workshop", "mainCharacter": "Kompei the Konpeito (a tiny spiky rainbow sugar candy) — a fresh, under-used character replacing the over-used Maru Matcha", "setting": "A small indigo-dyeing (aizome) craft studio down a cobbled Kyoto lane, with big wooden tubs of glowing indigo dye", "theme": "A happy accident can become the most beautiful part of what you make — let go of needing things perfect and embrace the unplanned", "spotlightTerm": "あい", "spotlightRomanization": "ai", "spotlightMeaning": "indigo blue", "premise": "Perfection-obsessed Kompei goes to an indigo-dyeing workshop wanting one flawless even-blue square, but when his clumsy hand slips and bunches the cloth, the accident blooms into a stunning unplanned star-pattern — and he learns to make 'real' instead of 'perfect,' even painting a pattern by sitting on the cloth.", "arc": "Starts rigidly chasing one perfect even square -> astonished that indigo turns from green to blue on its own (can't be forced) -> an accidental fold creates a gorgeous unplanned pattern -> begins making happy accidents on purpose and feels proud of a 'mistake' for the first time -> falls asleep under his accidental indigo cloth, content to be beautifully imperfect.", "reason": "#58 was a near-duplicate re-skin of canonical #54 (same Maru Matcha bringing the same rowdy friends to a quiet Kyoto space, repeating 'whisk slow, feel calm,' drawing with her bamboo whisk, teaching identical stillness-as-gift lesson). I kept lower-numbered #54 unchanged and fully rewrote #58 with a brand-new character, a hands-on messy craft activity, and a different emotional lesson (embracing imperfection/happy accidents) that appears nowhere else in the roadmap (distinct from #59's 'brave first try' which is about pride, not transformation of mistakes).", "collection": "japan", "path": "japan/stories/058-kompei-and-the-indigo-dye-workshop.md", "spotlightLabel": "Japanese Spotlight"}, {"number": 56, "oldTitle": "Dora Dorayaki and the Bamboo Forest Whisper", "newTitle": "Sen Senbei and the Summer Wind-Chimes", "newSlug": "sen-senbei-and-the-summer-wind-chimes", "mainCharacter": "Sen the Senbei (a flat golden rice cracker wrapped in seaweed) — a fresh, under-used character replacing the over-used Dora Dorayaki", "setting": "A summer wind-chime (fūrin) festival in the leafy courtyard of a Kyoto temple, hundreds of glass bells hanging from the trees", "theme": "The small things you make and give away can comfort a stranger you will never meet", "spotlightTerm": "ふうりん", "spotlightRomanization": "fūrin", "spotlightMeaning": "glass wind-chime", "premise": "Plain little Sen the Senbei, sure he is too small to make anything that matters, is invited by a translucent glassblower to paint glass wind-chimes and write kind notes on their paper tails — chimes that will be taken home by anonymous strangers — and witnesses a tired dumpling-child choose his bell and smile, discovering that an anonymous handmade kindness is one of the biggest things there is.", "arc": "Worries he is too small and plain to make anything meaningful -> shyly agrees to paint and inscribe a glass fūrin -> learns the chimes go to strangers he'll never meet, so writes the comfort he most needs himself -> makes many, each a small anonymous kindness -> watches a weary child choose his very first chime and smile in the breeze -> understands his tiny voice slipped into the big song and mattered all along.", "reason": "#56 was a thematic-execution overlap with canonical #53 (both: a fast/eager protagonist corrected by a wise slow elder in Kyoto, then learning the ordinary place is 'crammed' with secret quiet wonders, noticing falling leaves/petals). I kept lower-numbered #53 unchanged and rewrote #56 with a new character, a new craft activity (painting glass fūrin), a supportive (not corrective) elder, and a genuinely different lesson about anonymous generosity to strangers — distinct from #15 (delivering letters via a gadget) and #81 ('every voice adds to the song'), since here the emphasis is on small handmade gifts comforting people you'll never know.", "collection": "japan", "path": "japan/stories/056-sen-senbei-and-the-summer-wind-chimes.md", "spotlightLabel": "Japanese Spotlight"}];
phase('Rewrite stories')

const STYLE = `You write ONE cozy bedtime story for a 9-YEAR-OLD GIRL (ages 9-12) in the "Boba Bedtime Stories" style.
TONE: warm, playful, silly, cozy — Roald Dahl meets a vibrant food market. A laugh line in every major scene; a warm narrator who occasionally winks at the reader.
AGE SAFETY: nothing genuinely scary, sad, violent, or dark. Gentle cute spookiness only. Any "becoming a treat" moment must be JOYFUL and proud, never frightening.
LENGTH: 1800-2000 words of story. Fun within the first ~150 words.
VOCAB: weave in 3-5 local-language terms naturally; on FIRST use format as **native term** (romanization) = English. The header spotlight term is the key word.
This is a REWRITE to make the story DISTINCT from others — fully commit to the NEW premise, character, and lesson below. Give the main character a vivid physical description tied to its real food.`

const RET = { type:'object', additionalProperties:false, required:['path','title','wordCount','ok'],
  properties:{ path:{type:'string'}, title:{type:'string'}, wordCount:{type:'integer'}, ok:{type:'boolean'} } }

function prompt(s){
  const num = s.number
  const title = s.newTitle.replace(/^Story \d+:\s*/,'')
  return `${STYLE}

WRITE THIS STORY (a rewrite — ignore any previous version):
- Number: ${num}
- Title: ${title}
- Main Character: ${s.mainCharacter}
- Guest Characters: ${s.guests || 'None'}
- Setting: ${s.setting}
- Theme (must come through clearly and is DISTINCT from other stories): ${s.theme}
- ${s.spotlightLabel} term: ${s.spotlightTerm} (${s.spotlightRomanization}) = ${s.spotlightMeaning}
- Premise: ${s.premise}
- Arc: ${s.arc}
- EXACT file path to Write: ${s.path}

Use the Write tool to create the file at that exact path with this structure:

# Story ${num}: ${title}

**Main Character:** ${s.mainCharacter}
**Guest Characters:** ${s.guests || 'None'}
**Setting:** ${s.setting}
**Theme:** ${s.theme}
**${s.spotlightLabel}:** ${s.spotlightTerm} (${s.spotlightRomanization}) = ${s.spotlightMeaning}

---

<opening hook ~150 words>

<main narrative ~1500 words>

<warm ending>

---

## Goodnight Blessing
<soft sleepy closing ending with "Goodnight.">

## AI Image Prompts
1. <key scene>
2. <character portrait>
3. <closing scene>

Then return {path, title, wordCount, ok}.`
}

const results = await parallel(SPECS.map(s => () =>
  agent(prompt(s), { label:`rewrite:${s.collection}-${s.number}`, phase:'Rewrite stories', schema:RET })
    .then(r=>r).catch(()=>null)
))
const ok=results.filter(Boolean)
const failed=SPECS.filter((s,i)=>!results[i]).map(s=>`${s.collection}-${s.number}`)
log(`Rewrote ${ok.length}/${SPECS.length}; failed=[${failed.join(',')}]`)
return { wrote: ok.length, total: SPECS.length, failed }
